/**
 * IngrediScan non-food ingredient database: cosmetics, soaps, personal care,
 * detergents and household cleaners.
 *
 * Same shape as additives.js plus `domain`:
 *   code      – short unique id shown in the UI ("MIT", "SLS", "D5", "PPD"…)
 *   domain    – cosmetic | household | both
 *   category  – preservative | fragrance | uv-filter | surfactant | silicone |
 *               colorant | hair-dye | antimicrobial | solvent | bleach |
 *               caustic | acid | polymer | skin-active | other
 *   level     – high | medium | low | none
 *               high   = banned in EU cosmetics, CMR-classified, or a strong
 *                        sensitiser restricted for that reason
 *               medium = restricted with limits/warnings, frequent allergen,
 *                        corrosive household chemical, or environmental restriction
 *               low    = concern only for sensitive people or at high exposure
 *               none   = no notable concern (listed so the app shows a proper name)
 *   name      – { en, ro }
 *   aliases   – INCI names (the same on Romanian labels) + RO/EN common names.
 *               ALL-CAPS aliases (e.g. "MIT", "SLS") only match standalone capitals.
 *               "~" = up to three words in between.
 *   why       – { en, ro } one or two factual sentences citing the EU Cosmetics
 *               Regulation (EC) 1223/2009 and its amendments, the Detergents
 *               Regulation (EC) 648/2004, REACH, CLP, SCCS or IARC.
 *
 * Cosmetic ingredient lists use INCI names (Latin/English) even in Romania;
 * detergent labels list ingredient groups in Romanian with % bands
 * ("<5% agenți de suprafață anionici, fosfonați, parfumuri").
 *
 * Information only, not medical advice. Rules change: review periodically.
 */

function n(code, domain, category, level, en, ro, aliases, whyEn, whyRo) {
  return { code, domain, category, level, name: { en, ro }, aliases, why: { en: whyEn, ro: whyRo } };
}

